class WeatherSystem:
    CELSIUS = 'celsius'
    FAHRENHEIT = 'fahrenheit'

    def __init__(self, city) -> None:
        self._temperature = None
        self._weather = None
        self.city = city
        self._weather_list = {}

    def query(self, weather_list, tmp_units=CELSIUS):
        self._weather_list = weather_list
        if self.city not in weather_list:
            return False
        temperature = self._get_temperature_for_city()
        weather = self._get_weather_for_city()
        converted_temperature = self._convert_temperature(temperature, tmp_units)
        return converted_temperature, weather

    def set_city(self, city):
        self.city = city

    def _get_temperature_for_city(self):
        return self._weather_list[self.city]['temperature']

    def _get_weather_for_city(self):
        return self._weather_list[self.city]['weather']

    def _convert_temperature(self, temperature, target_units):
        source_units = self._weather_list[self.city]['temperature units']
        if source_units == target_units:
            return temperature
        if source_units == FAHRENHEIT and target_units == CELSIUS:
            return self.fahrenheit_to_celsius(temperature)
        if source_units == CELSIUS and target_units == FAHRENHEIT:
            return self.celsius_to_fahrenheit(temperature)
        return temperature

    def celsius_to_fahrenheit(self, temperature):
        return (temperature * 9/5) + 32

    def fahrenheit_to_celsius(self, temperature):
        return (temperature - 32) * 5/9
